package com.bank.spark.model;

// A candidate partition column with its distinct-value count.
public class PartitionCandidate {
    private final String column;
    private final long distinctValues;   // cardinality
    private final boolean queriedOften;   // aligns with access patterns?

    public PartitionCandidate(String column, long distinctValues, boolean queriedOften) {
        this.column = column;
        this.distinctValues = distinctValues;
        this.queriedOften = queriedOften;
    }

    public String getColumn() { return column; }
    public long getDistinctValues() { return distinctValues; }
    public boolean isQueriedOften() { return queriedOften; }
}
