package com.bank.spark.service;

import com.bank.spark.model.PartitionCandidate;

// Evaluates whether a partition column is healthy given dataset size.
public class PartitionDesignEvaluator {

    private static final long HEALTHY_MIN_BYTES = 128L * 1024 * 1024; // 128 MB
    private static final long MAX_SAFE_PARTITIONS = 50_000;           // beyond this: risk

    // Returns a verdict string for the candidate against total dataset bytes.
    public String evaluate(PartitionCandidate c, long totalBytes) {
        long bytesPerDir = c.getDistinctValues() == 0 ? totalBytes : totalBytes / c.getDistinctValues();

        if (!c.isQueriedOften()) {
            return "AVOID: '" + c.getColumn() + "' is not filtered by queries — partitioning gives no pruning";
        }
        if (c.getDistinctValues() > MAX_SAFE_PARTITIONS) {
            return "DANGER: '" + c.getColumn() + "' has " + c.getDistinctValues()
                    + " distinct values → directory explosion, tiny files, DRIVER OOM risk";
        }
        if (bytesPerDir < HEALTHY_MIN_BYTES) {
            return "WEAK: '" + c.getColumn() + "' gives only " + (bytesPerDir / (1024 * 1024))
                    + " MB/dir — small-file problem likely";
        }
        return "GOOD: '" + c.getColumn() + "' — " + c.getDistinctValues()
                + " dirs, ~" + (bytesPerDir / (1024 * 1024)) + " MB each, aligned with queries";
    }
}
