package com.bank.spark;

import com.bank.spark.model.PartitionCandidate;
import com.bank.spark.service.PartitionDesignEvaluator;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PartitionDesignDemo {

    private static final Logger log = Logger.getLogger(PartitionDesignDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PartitionDesignEvaluator evaluator = new PartitionDesignEvaluator();
        long totalBytes = 2_000L * 1024 * 1024 * 1024; // 2 TB transactions dataset

        List<PartitionCandidate> candidates = List.of(
                new PartitionCandidate("accountId", 10_000_000L, true),  // high cardinality
                new PartitionCandidate("txnTimestamp", 86_400_000L, true), // extreme cardinality
                new PartitionCandidate("branch", 500L, true),              // good
                new PartitionCandidate("txnMonth", 36L, true),             // good
                new PartitionCandidate("customerName", 8_000_000L, false)  // not queried + high card
        );

        for (PartitionCandidate c : candidates) {
            String verdict = evaluator.evaluate(c, totalBytes);
            if (verdict.startsWith("DANGER")) {
                log.severe(verdict);
            } else if (verdict.startsWith("AVOID") || verdict.startsWith("WEAK")) {
                log.warning(verdict);
            } else {
                log.info(verdict);
            }
        }

        log.info("Recommendation: partitionBy(\"branch\", \"txnMonth\"); bucket by accountId for lookups.");
    }
}

